using Microsoft.Dynamics365.LocalizationFramework;
/// <summary>
/// This extension of <c>ERDocumentAttachmentDataContract</c> class helps to run ER report. 
/// </summary>
[ExtensionOf(classStr(ERDocumentAttachmentDataContract))]
final class AVADAIERDocumentAttachmentDataContract_Cls_Extension
{
    private ERFileDestinationMemory fileDestination;
}

Method.Source:
/// <summary>
/// Inilializes the contract class object.
/// </summary>
/// <remarks>
/// The mapping run object settings will be changed for document attachment generation.
/// </remarks>
/// <param name = "_mappingRun">Configured mapping run object.</param>
public void avaDAIinitFromMappingRun(ERIFormatMappingRun _mappingRun)
{
    this.avaDAIresetDestinationAction(_mappingRun);

    fileDestination = new ERFileDestinationMemory();
    _mappingRun.withFileDestination(fileDestination).run();
}

/// <summary>
/// Gets data stream for generated report.
/// </summary>
/// <returns>GER report data stream.</returns>
public System.IO.Stream avaDAIGetERStream()
{
    return fileDestination
        ? fileDestination.GetStream()
        : null;
}

private void avaDAIresetDestinationAction(ERIFormatMappingRun _mappingRun)
{
    ERIFormatMappingRunWithDestinationAction mappingRunWithAction = _mappingRun as ERIFormatMappingRunWithDestinationAction;
    if (mappingRunWithAction)
    {
        mappingRunWithAction.withDestinationAction(ERDestinationAction::NoAction);
    }
}
